const feeds = [
 ['World','BBC','https://feeds.bbci.co.uk/news/world/rss.xml'],
 ['Business','BBC','https://feeds.bbci.co.uk/news/business/rss.xml'],
 ['Technology','BBC','https://feeds.bbci.co.uk/news/technology/rss.xml'],
 ['Science','BBC','https://feeds.bbci.co.uk/news/science_and_environment/rss.xml'],
 ['World','The Guardian','https://www.theguardian.com/world/rss']
];
function decode(s=''){return s.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g,'$1').replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>');}
function parse(xml,category,source){return [...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].slice(0,12).map(([,s])=>{const get=k=>decode((s.match(new RegExp('<'+k+'[^>]*>([\\s\\S]*?)</'+k+'>'))||[])[1]||'');return {title:get('title'),summary:get('description'),url:get('link'),published:get('pubDate'),category,source};}).filter(s=>s.title&&/^https:\/\//.test(s.url)&&Number.isFinite(Date.parse(s.published)));}
export default {async fetch(request,env,ctx){const u=new URL(request.url);if(u.pathname==='/api/news'){
 let cache;const key=new Request(u.origin+'/api/news');try{cache=globalThis.caches?.default;const cached=await cache?.match(key);if(cached)return cached;}catch{cache=undefined;}
 const results=await Promise.allSettled(feeds.map(async([c,s,url])=>{const r=await fetch(url,{signal:AbortSignal.timeout(9000),headers:{'User-Agent':'GlobalEdit/1.0'}});if(!r.ok)throw Error('Feed unavailable');return parse(await r.text(),c,s);}));
 const seen=new Set();const stories=results.flatMap(r=>r.status==='fulfilled'?r.value:[]).filter(s=>{const k=s.title.toLowerCase();if(seen.has(k))return false;seen.add(k);return Date.now()-Date.parse(s.published)<3*86400000;}).sort((a,b)=>Date.parse(b.published)-Date.parse(a.published));
 if(!stories.length)return Response.json({error:'News sources are temporarily unavailable. Please try again shortly.'},{status:503});
 const response=Response.json({updated:new Date().toISOString(),stories},{headers:{'Cache-Control':'public, max-age=900'}});if(cache)ctx.waitUntil(cache.put(key,response.clone()).catch(()=>{}));return response;
 }if(u.pathname!=='/')return new Response('Not found',{status:404});return new Response(html,{headers:{'Content-Type':'text/html; charset=utf-8','X-Content-Type-Options':'nosniff'}});}};
const html=String.raw`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Daily Lens — Your daily perspective</title><meta name="description" content="A quieter way to catch up. A personal newspaper of global highlights, with concise source excerpts and original reporting."><style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Libre+Caslon+Display&display=swap');
:root{--paper:#f7f5ef;--ink:#242b25;--muted:#73766d;--line:#d9d9cc;--green:#386346}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:14px 'DM Sans',sans-serif}button,a,input{font:inherit}button{cursor:pointer}a{color:inherit}header,main,footer{max-width:1240px;margin:auto;padding:0 36px}.utility{display:flex;justify-content:space-between;padding:22px 0;border-bottom:1px solid var(--line);font-size:11px;letter-spacing:1px;text-transform:uppercase}.live{color:var(--green)}.masthead{text-align:center;padding:26px 0 24px}.masthead h1{font:clamp(52px,8vw,100px)/1 'Libre Caslon Display',Georgia,serif;margin:0;letter-spacing:-3px}.masthead p{color:var(--muted);margin:12px 0 0;font-size:12px;letter-spacing:2px}.nav{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:2px solid var(--ink);border-bottom:1px solid var(--ink);padding:8px 0}.tabs{display:flex;gap:8px;flex-wrap:wrap}.nav button{background:none;border:0;padding:10px 14px;color:var(--muted);border-radius:3px}.nav button.active{background:var(--ink);color:var(--paper)}.intro{display:flex;justify-content:space-between;gap:20px;align-items:end;padding:36px 0 24px}.eyebrow{font-size:10px;font-weight:700;letter-spacing:2px;text-transform:uppercase;color:var(--green)}h2{font:42px/1.1 'Libre Caslon Display',Georgia,serif;margin:8px 0}.intro p{color:var(--muted);margin:0 0 3px}.edition{font-size:11px;color:var(--muted);text-align:right}.layout{display:grid;grid-template-columns:minmax(0,1fr) 270px;gap:36px;border-top:1px solid var(--line);padding-top:24px}.stories{display:grid;grid-template-columns:1fr 1fr;gap:0 26px}.story{padding:23px 0;border-bottom:1px solid var(--line);position:relative}.story:first-child{grid-column:1/-1;padding-top:0}.story h3{font:29px/1.13 'Libre Caslon Display',Georgia,serif;margin:12px 25px 12px 0}.story:first-child h3{font-size:45px;max-width:720px}.story p{font-size:13px;line-height:1.8;color:#656a60;margin:12px 0 18px}.story .meta{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.7px}.story a{text-decoration:none}.story a:hover{text-decoration:underline;text-underline-offset:4px}.save{position:absolute;right:0;top:22px;border:1px solid var(--line);background:none;width:29px;height:31px;border-radius:3px;color:var(--muted)}.story:first-child .save{top:0}.save.on{background:var(--green);color:white}.read{font-size:11px;font-weight:700;color:var(--green)}aside{border-left:1px solid var(--line);padding-left:26px}.note{background:#e8ecdf;padding:24px;margin-bottom:28px}.globe{font-size:48px;font-family:Georgia;color:var(--green)}.note h3{font:30px/1.1 'Libre Caslon Display',Georgia,serif;margin:12px 0}.note p,aside p{font-size:12px;line-height:1.8;color:#69705f}.smalltitle{font-size:10px;text-transform:uppercase;letter-spacing:1.5px;font-weight:700}aside ol{padding-left:18px;line-height:2.4;color:var(--muted);font-size:12px}footer{margin:42px auto 0;padding-top:20px;padding-bottom:28px;border-top:2px solid var(--ink);display:flex;justify-content:space-between;color:var(--muted);font-size:11px}.status{padding:50px 0;grid-column:1/-1;color:var(--muted);line-height:1.7}.retry{padding:10px 18px;background:var(--green);color:white;border:0;border-radius:3px;margin-top:15px}.search{border:1px solid var(--line);padding:10px;background:transparent;max-width:160px}.refresh{border:0;background:transparent;color:var(--green);padding:0;margin-top:12px;font-size:11px}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--green);outline-offset:4px}@media(max-width:800px){header,main,footer{padding-left:20px;padding-right:20px}.layout{grid-template-columns:1fr}aside{border-left:0;padding-left:0;display:grid;grid-template-columns:1fr 1fr;gap:24px}.nav{align-items:start;flex-direction:column}.intro{align-items:start}.intro p{max-width:240px;line-height:1.6}.edition{max-width:140px}.masthead p{font-size:10px}.story:first-child h3{font-size:36px}.search{max-width:100%;width:100%}}@media(max-width:500px){.stories{grid-template-columns:1fr}.story:first-child h3{font-size:33px}.intro{flex-direction:column}.edition{text-align:left;max-width:none}.utility{font-size:9px}.tabs{gap:0}.nav button{padding:9px 10px}aside{grid-template-columns:1fr}footer{gap:20px;line-height:1.7}}

/* The Daily Lens — evening journal edition */
:root{--paper:#f5f1e9;--ink:#162c34;--muted:#737872;--line:#d9d3c7;--green:#9a593a}
body{background:radial-gradient(ellipse at 0 0,#e6dfd0,transparent 50%),var(--paper)}
header{max-width:none;background:#102b34;color:#f8f2e7;padding:0 max(36px,calc((100vw - 1168px)/2));position:relative;overflow:hidden}
header:before{content:'';position:absolute;width:520px;height:520px;right:-160px;top:-310px;border:1px solid #b99b6e35;border-radius:50%;box-shadow:0 0 0 45px #b99b6e0b,0 0 0 90px #b99b6e0b;pointer-events:none}
.utility{border-color:#ffffff20;font-size:10px;letter-spacing:1.5px;position:relative}.live{color:#e2bf88}.live:before{content:'';display:inline-block;width:6px;height:6px;margin-right:8px;background:#e2bf88;border-radius:50%;box-shadow:0 0 0 4px #e2bf8815}
.masthead{padding:38px 0 36px;position:relative}.masthead:before{content:'EST. 2026  /  THE PERSONAL JOURNAL';display:block;font-size:9px;letter-spacing:3px;color:#c5ab80;margin-bottom:16px}.masthead h1{font-size:clamp(55px,8.4vw,108px);letter-spacing:-4px;text-shadow:0 3px 25px #0002}.masthead h1 span{color:#d8ab70!important}.masthead p{color:#bfcbc9;letter-spacing:3.5px;font-size:10px;margin-top:17px}
.nav{border-top:1px solid #d7b98270;border-bottom:0;padding:13px 0;position:relative}.nav button{color:#c4d0cd;border-radius:30px;font-size:12px;padding:10px 17px;transition:background .2s,color .2s}.nav button:hover{background:#ffffff12;color:white}.nav button.active{background:#e8c899;color:#142f37}.search{color:#f6eddf;border-color:#ffffff30;border-radius:24px;max-width:200px;padding:11px 17px;background:#ffffff08;font-size:11px}.search::placeholder{color:#bfcbc9}
main{padding-top:8px}.intro{padding:32px 0 27px}.intro .eyebrow{letter-spacing:2.6px;font-size:9px}h2{font-size:46px;letter-spacing:-1px}.intro p{font-size:12px}.edition{padding:13px 18px;border:1px solid var(--line);border-radius:4px;background:#ffffff55;font-size:10px}.refresh{font-size:11px;font-weight:600}.layout{border-top:0;padding-top:0;gap:28px;grid-template-columns:minmax(0,1fr) 260px}.stories{gap:20px;align-items:start}
.story{padding:25px;background:#fffcf6;border:1px solid #ded8cc;border-radius:5px;box-shadow:0 4px 14px #182d3410;transition:transform .2s,box-shadow .2s;overflow:hidden}.story:hover{transform:translateY(-3px);box-shadow:0 10px 25px #182d3418}.story h3{font-size:30px;letter-spacing:-.4px;margin-top:16px}.story p{color:#69716b;font-size:12px;line-height:1.85}.story .eyebrow{font-size:9px;padding-right:30px}.story .meta{font-size:9px;letter-spacing:.5px}.story .read{display:inline-block;border-top:1px solid #dfd9cf;padding-top:14px;width:100%;font-size:10px;letter-spacing:.3px}.save{right:18px;top:18px;border-radius:50%;width:30px;height:30px;background:#f6f1e8;border-color:#ddd6c8}.save.on{background:var(--green);border-color:var(--green)}
.story:first-child{padding:39px;background:linear-gradient(115deg,#183a42,#102b34);color:#fff7e9;border:1px solid #29454b;min-height:345px;isolation:isolate}.story:first-child:before{content:'';position:absolute;z-index:-1;width:330px;height:330px;right:-140px;top:25px;border-radius:50%;border:1px solid #dfbd7e35;box-shadow:0 0 0 27px #dfbd7e09,0 0 0 55px #dfbd7e09,0 0 0 83px #dfbd7e09;pointer-events:none}.story:first-child:after{content:'01 / IN FOCUS';position:absolute;bottom:25px;right:28px;color:#d8b77c6b;font-size:9px;letter-spacing:2px;pointer-events:none}.story:first-child h3{font-size:clamp(32px,3.6vw,48px);line-height:1.08;max-width:650px;margin:20px 5px 20px 0}.story:first-child .eyebrow{color:#e1ba7f}.story:first-child p{color:#c0cfcb;max-width:580px;font-size:13px}.story:first-child .meta{color:#b2c3bf}.story:first-child .read{border-top-color:#ffffff25;color:#e1ba7f;width:auto;padding-right:55px}.story:first-child .save{right:22px;top:24px;background:#ffffff0d;color:#e6c99e;border-color:#ffffff35}
aside{border-left:0;padding-left:0}.note{background:#e7dfcf;padding:27px;border-radius:5px;position:relative;overflow:hidden;border:1px solid #dcd1be}.globe{font-size:78px;line-height:1;margin-bottom:20px;color:#9a593a}.note:after{content:'THE BIGGER PICTURE';position:absolute;right:-58px;top:86px;transform:rotate(90deg);font-size:8px;letter-spacing:3px;color:#9a593a88}.note h3{font-size:36px}.note p{font-size:12px}.note+.sidebar-details{padding:5px 16px}aside ol{list-style:none;counter-reset:topics;padding:0}aside li{counter-increment:topics;border-bottom:1px solid var(--line);padding:7px 0;font-size:11px}aside li:before{content:'0' counter(topics);color:var(--green);font-size:9px;margin-right:15px}.smalltitle{font-size:9px;letter-spacing:1.7px}aside p{font-size:11px}footer{border-top:1px solid var(--ink);margin-top:44px;padding-top:25px;padding-bottom:35px}.status{padding:45px 28px;background:#fffcf6;border:1px solid var(--line);border-radius:5px;min-height:200px}.retry{border-radius:30px}.story a:focus-visible{outline-color:#c69451}
@media(prefers-reduced-motion:reduce){.story,.nav button{transition:none}.story:hover{transform:none}}
@media(max-width:800px){header{padding:0 22px}.utility span:last-child{display:none}.masthead{padding:30px 0}.nav{flex-direction:row;flex-wrap:wrap}.search{max-width:200px;width:auto}.layout{grid-template-columns:1fr}.story:first-child{min-height:0}aside{display:grid;grid-template-columns:1fr 1fr;gap:25px}.note{margin-bottom:0}.edition{max-width:180px}.intro p{max-width:none}.masthead h1{letter-spacing:-2px}}
@media(max-width:500px){header,main,footer{padding-left:18px;padding-right:18px}.masthead h1{font-size:54px}.masthead p{font-size:8px;letter-spacing:2px}.masthead:before{font-size:8px;letter-spacing:2px}.utility{font-size:8px;letter-spacing:.5px}.nav{gap:14px;padding:12px 0 18px}.tabs{gap:3px}.nav button{font-size:10px;padding:8px 11px}.search{width:100%;max-width:none}.intro{gap:16px;padding:25px 0}.intro h2{font-size:39px}.edition{max-width:none;width:100%;display:flex;align-items:center;justify-content:space-between;padding:12px 15px}.refresh{margin:0}.stories{grid-template-columns:1fr;gap:15px}.story{padding:24px}.story:first-child{padding:29px 25px}.story:first-child h3{font-size:35px;margin-right:0}.story:first-child:after{display:none}.story h3{font-size:31px}aside{grid-template-columns:1fr;margin-top:8px}.note{padding:25px}.note h3 br{display:none}.globe{float:right;font-size:64px;margin:0 10px 10px 20px}.note .eyebrow{padding-top:4px}.note h3{font-size:34px}.note:after{display:none}footer{flex-direction:column;gap:12px}}

</style></head><body><header><div class="utility"><span id="date"></span><span class="live">Your daily perspective</span><span>Independent minds. Wider world.</span></div><div class="masthead"><h1>The Daily Lens<span style="color:var(--green)">.</span></h1><p>A WORLD OF NEWS. JUST THE ESSENTIALS.</p></div><nav class="nav" aria-label="News categories"><div class="tabs" id="tabs"></div><input class="search" id="search" aria-label="Search stories" placeholder="Search the edition ↗"></nav></header><main><section class="intro"><div><div class="eyebrow">The daily briefing</div><h2>The world, considered.</h2><p>The stories shaping our world, in a few quiet minutes.</p></div><div class="edition"><div id="updated">Connecting to news sources…</div><button class="refresh" id="refresh">Refresh edition ↻</button></div></section><div class="layout"><section id="stories" class="stories" aria-live="polite"><div class="status">Gathering the latest global headlines…</div></section><aside><div class="note"><div class="globe">◎</div><div class="eyebrow">Less noise. More world.</div><h3>Your window<br>to the bigger picture.</h3><p>A considered selection of global reporting. Take a breath, catch up, and get on with your day.</p></div><div class="sidebar-details"><div class="smalltitle">Inside this edition</div><ol><li>World &amp; diplomacy</li><li>Business &amp; the economy</li><li>Technology &amp; innovation</li><li>Science &amp; our planet</li></ol><hr style="border:0;border-top:1px solid var(--line);margin:24px 0"><div class="smalltitle">A note on the news</div><p>Headlines and short excerpts come directly from BBC and The Guardian feeds. Selection uses recency, topic variety, and duplicate removal. This edition does not yet use AI-written summaries.</p><p>Feeds refresh when you visit, with a 15-minute cache. Source dates appear on every story. Saved stories stay in this browser.</p></div></aside></div></main><footer><span style="font-family:Georgia;font-size:18px;color:var(--ink)">The Daily Lens.</span><span>A quieter way to stay informed. · Read the original. See the whole picture.</span></footer><script>
let all=[],category='Highlights',query='',saved=new Map();try{saved=new Map(JSON.parse(localStorage.getItem('global-edit-saved')||'[]'))}catch{}const cats=['Highlights','World','Business','Technology','Science','Saved'];const el=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
el('date').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});
function render(){el('tabs').innerHTML=cats.map(c=>'<button aria-pressed="'+(category===c)+'" class="'+(category===c?'active':'')+'" data-cat="'+c+'">'+c+(c==='Saved'?' ('+saved.size+')':'')+'</button>').join('');let list=category==='Saved'?[...saved.values()]:all;if(category==='Highlights'){const pick=[];for(const cat of ['World','Business','Technology','Science']){const item=all.find(s=>s.category===cat);if(item)pick.push(item)}list=[...pick,...all.filter(s=>!pick.includes(s))].slice(0,7);}else if(category!=='Saved')list=list.filter(s=>s.category===category);list=list.filter(s=>(s.title+' '+s.summary).toLowerCase().includes(query));el('stories').innerHTML=list.length?list.map((s,i)=>'<article class="story"><div class="eyebrow">'+(category==='Highlights'&&i===0?'The lead story · ':'')+esc(s.category)+'</div><button class="save '+(saved.has(s.url)?'on':'')+'" aria-label="'+(saved.has(s.url)?'Unsave':'Save')+' story" aria-pressed="'+saved.has(s.url)+'" data-save="'+esc(s.url)+'">'+(saved.has(s.url)?'✓':'+')+'</button><h3><a href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a></h3><div class="meta">'+esc(s.source)+' · '+esc(new Date(s.published).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))+'</div><p>'+esc(s.summary)+'</p><a class="read" href="'+esc(s.url)+'" target="_blank" rel="noopener noreferrer">Read original reporting ↗</a></article>').join(''):'<div class="status">'+(category==='Saved'?'Your reading list starts here. Use + on a story to save it.':'No matching stories. Try another topic or search.')+'</div>';}
el('tabs').addEventListener('click',e=>{if(e.target.dataset.cat){category=e.target.dataset.cat;render()}});el('search').addEventListener('input',e=>{query=e.target.value.toLowerCase();render()});el('stories').addEventListener('click',e=>{const url=e.target.dataset.save;if(!url)return;if(saved.has(url))saved.delete(url);else{const s=all.find(s=>s.url===url);if(s)saved.set(url,s)}try{localStorage.setItem('global-edit-saved',JSON.stringify([...saved]))}catch{}render()});
async function load(){el('refresh').disabled=true;el('updated').textContent='Checking news sources…';try{const r=await fetch('/api/news');if(!r.ok)throw Error();const data=await r.json();all=data.stories;el('updated').textContent='Feed checked '+new Date(data.updated).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});render()}catch{el('updated').textContent='Could not refresh sources';if(!all.length)el('stories').innerHTML='<div class="status">The news feeds are temporarily unavailable. Your saved stories are still accessible.<br><button class="retry" onclick="load()">Try again</button></div>'}finally{el('refresh').disabled=false}}el('refresh').onclick=load;render();load();
</script></body></html>`;
